<script setup lang="ts">
import {ref,onMounted} from 'vue'
const props=defineProps<{contactId:number;role:string;leaseToken:string;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const rows=ref<any[]>([]),page=ref(1),count=ref(0),file=ref<File|null>(null),input=ref<HTMLInputElement|null>(null),busy=ref(false),error=ref('')
let requestId=crypto.randomUUID()
function select(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null;requestId=crypto.randomUUID()}
async function load(){try{const result=await props.request(`contacts/${props.contactId}/documents/?page=${page.value}`);rows.value=result.results;count.value=result.count}catch(e:any){error.value=e.message}}
async function upload(){if(!file.value)return;busy.value=true;error.value='';try{const data=new FormData();data.append('file',file.value);data.append('request_id',requestId);if(props.role!=='advisor')data.append('token',props.leaseToken);await props.request(`contacts/${props.contactId}/documents/`,data);file.value=null;if(input.value)input.value.value='';requestId=crypto.randomUUID();page.value=1;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function download(row:any){busy.value=true;error.value='';try{const blob=await props.request(`contacts/${props.contactId}/documents/${row.id}/download/`);const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=row.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><h3>{{role==='advisor'?'Mes documents':'Documents du dossier'}}</h3><p>PDF, PNG ou JPEG · 5 Mo maximum par fichier. Les documents internes sont réservés aux setters et à l’administration. Chaque conseiller voit ses propres documents ; l’administration peut tous les consulter.</p><p v-if="error" role="alert">{{error}}</p><form @submit.prevent="upload"><input ref="input" type="file" accept=".pdf,.png,.jpg,.jpeg" :disabled="busy||(role!=='advisor'&&!leaseToken)" @change="select"><button class="primary" :disabled="busy||!file||(role!=='advisor'&&!leaseToken)">Ajouter le document</button></form><p v-if="role!=='advisor'&&!leaseToken">Prenez en charge la fiche pour ajouter un document interne.</p><article v-for="row in rows" :key="row.id"><strong>{{row.filename}}</strong><small> · {{Math.ceil(row.size/1024)}} Ko · {{row.channel==='internal'?'Interne':'Conseiller'}} · {{new Date(row.created_at).toLocaleString('fr-FR')}}</small><button class="secondary" :disabled="busy" @click="download(row)">Télécharger</button></article><p v-if="!rows.length">Aucun document visible.</p><p>{{count}} document(s) · page {{page}}</p><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button><button class="secondary" :disabled="busy" @click="load">Actualiser</button></section></template>
